import{_ as e,o as a,c as d,a5 as l}from"./chunks/framework.CsGesDJn.js";const m=JSON.parse('{"title":"Điều hướng, bố cục và data demo liên kết: kế hoạch","description":"","frontmatter":{},"headers":[],"relativePath":"feature/navigation-ux-linked-demo-data/plan.md","filePath":"feature/navigation-ux-linked-demo-data/plan.md"}'),i={name:"feature/navigation-ux-linked-demo-data/plan.md"};function o(n,t,c,r,s,h){return a(),d("div",null,[...t[0]||(t[0]=[l('<h1 id="đieu-huong-bo-cuc-va-data-demo-lien-ket-ke-hoach" tabindex="-1">Điều hướng, bố cục và data demo liên kết: kế hoạch <a class="header-anchor" href="#đieu-huong-bo-cuc-va-data-demo-lien-ket-ke-hoach" aria-label="Permalink to &quot;Điều hướng, bố cục và data demo liên kết: kế hoạch&quot;">​</a></h1><p><strong>Goal:</strong> Thực hiện <a href="./spec.html">spec.md</a>: tab dưới trên mobile, màn hồ sơ Client, gọn nút, nhóm sidebar web, 5 tài khoản demo cùng tổ chức và biểu đồ có số liệu.</p><p><strong>Architecture:</strong> Mobile thêm một lớp tab bên trong drawer hiện có; stack cũ giữ nguyên làm nội dung từng tab. Web chỉ đổi cấu hình sidebar. Data dùng một seeder tuỳ chọn mới, chạy sau <code>seed-admin-demo</code> có sẵn.</p><p><strong>Tech Stack:</strong> Expo 56, React Navigation 7, <code>react-native-svg</code>; React, Vite, recharts; Spring Boot, Postgres local, Mongo Atlas DB <code>brandhub</code>.</p><h2 id="global-constraints" tabindex="-1">Global Constraints <a class="header-anchor" href="#global-constraints" aria-label="Permalink to &quot;Global Constraints&quot;">​</a></h2><ul><li>Tên vai trò chỉ dùng <code>Guest</code>, <code>Owner</code>, <code>Manager</code>, <code>Creator</code>, <code>Client</code>, <code>Admin</code>.</li><li>Không Livestream trong data hoặc UI mới. Nền tảng chỉ Facebook, Instagram, TikTok, Threads. Thanh toán SePay/VietQR.</li><li>Không thêm API, không đổi quyền backend, không xoá route.</li><li>Chuỗi mới có i18n; màu lấy từ token theme.</li><li>Vùng chạm mới tối thiểu 44×44; tối đa 5 tab.</li><li>Không commit khi chưa được yêu cầu.</li></ul><h2 id="review-focus" tabindex="-1">Review Focus <a class="header-anchor" href="#review-focus" aria-label="Permalink to &quot;Review Focus&quot;">​</a></h2><ol><li>Vai trò đổi giữa hai Workspace làm tab hiện tại biến mất: phải về Tổng quan, không màn trắng.</li><li>Link sâu vào màn con: back phải về đúng gốc tab, không thoát app.</li><li>Seed chạy lại hoặc thất bại giữa chừng: không nhân đôi, không để data nửa vời, gỡ được.</li><li><code>Client</code> một hồ sơ hoặc chưa có hồ sơ: màn vẫn dùng được.</li><li>Đổi ngôn ngữ làm app remount: giữ đúng tab và màn đang mở.</li></ol><h2 id="cau-truc-file" tabindex="-1">Cấu trúc file <a class="header-anchor" href="#cau-truc-file" aria-label="Permalink to &quot;Cấu trúc file&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Khu vực</th><th style="text-align:left;">File</th><th style="text-align:left;">Thay đổi</th></tr></thead><tbody><tr><td style="text-align:left;">Seed</td><td style="text-align:left;"><code>resources/seed/linked-demo.sql</code></td><td style="text-align:left;">Mới: sửa liên kết tài khoản, thêm billing, kiểm duyệt, thông báo</td></tr><tr><td style="text-align:left;">Seed</td><td style="text-align:left;"><code>seed/LinkedDemoSeeder.java</code></td><td style="text-align:left;">Mới: profile <code>seed-linked-demo</code>, chạy SQL và seed task, post vào Mongo</td></tr><tr><td style="text-align:left;">Seed</td><td style="text-align:left;"><code>resources/seed/linked-demo-remove.sql</code>, cờ <code>--remove</code></td><td style="text-align:left;">Mới: gỡ theo <code>seedTag</code> và <code>merchant_account=&#39;DEMO&#39;</code></td></tr><tr><td style="text-align:left;">Seed</td><td style="text-align:left;"><code>dev-quick-login.sql</code>, <code>TaskSampleSeeder.java</code></td><td style="text-align:left;">Bỏ Livestream</td></tr><tr><td style="text-align:left;">Mobile</td><td style="text-align:left;"><code>navigation/WorkspaceTabBar.tsx</code>, <code>navigation/tabs.ts</code>, <code>components/common/AppTabBar.tsx</code></td><td style="text-align:left;">Mới: tab theo vai trò, gắn vào <code>screenLayout</code> của drawer; không thêm thư viện</td></tr><tr><td style="text-align:left;">Mobile</td><td style="text-align:left;"><code>navigation/AdminStackNavigator.tsx</code></td><td style="text-align:left;">5 tab Admin trong <code>layout</code> của stack</td></tr><tr><td style="text-align:left;">Mobile</td><td style="text-align:left;"><code>navigation/AdminStackNavigator.tsx</code>, <code>MainDrawerNavigator.tsx</code>, <code>AppNavigator.tsx</code></td><td style="text-align:left;">Nối lớp tab</td></tr><tr><td style="text-align:left;">Mobile</td><td style="text-align:left;"><code>components/sidebar/SidebarContent.tsx</code>, <code>components/common/GlobalFab.tsx</code></td><td style="text-align:left;">Drawer chỉ đổi Workspace; FAB tránh tab</td></tr><tr><td style="text-align:left;">Mobile</td><td style="text-align:left;"><code>screens/admin/AdminMoreScreen.tsx</code></td><td style="text-align:left;">Mới: trang Thêm của Admin</td></tr><tr><td style="text-align:left;">Mobile</td><td style="text-align:left;"><code>components/admin/AdminCharts.tsx</code></td><td style="text-align:left;">Mới: biểu đồ tăng trưởng, trạng thái, doanh thu</td></tr><tr><td style="text-align:left;">Mobile</td><td style="text-align:left;"><code>screens/more/ClientProfileScreen.tsx</code></td><td style="text-align:left;">Mới: màn hồ sơ Client</td></tr><tr><td style="text-align:left;">Mobile</td><td style="text-align:left;"><code>services/workspaceService.ts</code>, <code>utils/navAccess.ts</code>, <code>screens/more/MoreScreen.tsx</code></td><td style="text-align:left;">Đổi hồ sơ, quyền màn mới, gọn nhóm</td></tr><tr><td style="text-align:left;">Mobile</td><td style="text-align:left;"><code>screens/auth/LoginScreen.tsx</code></td><td style="text-align:left;">Creator là <code>user13@</code></td></tr><tr><td style="text-align:left;">Mobile</td><td style="text-align:left;">Màn trong spec 4.3</td><td style="text-align:left;">Chia lại nút</td></tr><tr><td style="text-align:left;">Mobile</td><td style="text-align:left;"><code>i18n/locales/en.json</code></td><td style="text-align:left;">Chuỗi mới</td></tr><tr><td style="text-align:left;">Web</td><td style="text-align:left;"><code>sidebarNavConfig.ts</code>, <code>Sidebar.tsx</code></td><td style="text-align:left;">Nhóm con cho <code>create</code></td></tr><tr><td style="text-align:left;">Web</td><td style="text-align:left;"><code>Navbar.tsx</code>, <code>DevQuickLogin.tsx</code></td><td style="text-align:left;">Breadcrumb, bỏ <code>landingPath</code></td></tr><tr><td style="text-align:left;">Web</td><td style="text-align:left;"><code>i18n/locales/vi.json</code>, <code>en.json</code></td><td style="text-align:left;">Khoá nhóm con</td></tr></tbody></table><h2 id="luong-data" tabindex="-1">Luồng data <a class="header-anchor" href="#luong-data" aria-label="Permalink to &quot;Luồng data&quot;">​</a></h2><ol><li><code>seed-postgres</code> và <code>seed-mongo</code> đã chạy (hiện trạng).</li><li>Chạy <code>seed-admin-demo</code>: 1.240 user, 48 agency, strike, chế tài; ghi thêm post <code>seed_tag=admin-demo</code> vào Mongo.</li><li>Chạy <code>seed-linked-demo</code>: sửa liên kết 5 tài khoản, billing cho Circus Digital và các agency của <code>user177@</code>, task và post cho TH True Milk.</li></ol><p><code>seed_runs</code> ngăn chạy lại. Sửa tại chỗ chỉ đụng: chủ sở hữu Circus Digital, các dòng <code>MANAGER</code> của <code>user177@</code>, hồ sơ Client của TH True Milk.</p><h2 id="thu-tu" tabindex="-1">Thứ tự <a class="header-anchor" href="#thu-tu" aria-label="Permalink to &quot;Thứ tự&quot;">​</a></h2><p>Seed trước để có data thật khi kiểm tra UI. Sau đó tab mobile, Admin, hồ sơ Client, trang Thêm, chia nút, web, kiểm thử cuối.</p><h2 id="rui-ro" tabindex="-1">Rủi ro <a class="header-anchor" href="#rui-ro" aria-label="Permalink to &quot;Rủi ro&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Rủi ro</th><th style="text-align:left;">Cách xử lý</th></tr></thead><tbody><tr><td style="text-align:left;">Ghi nhầm môi trường Atlas</td><td style="text-align:left;">Từ chối khi profile <code>prod</code>/<code>production</code>; in host, DB và số bản ghi trước khi ghi</td></tr><tr><td style="text-align:left;">Backend đổi cấu trúc billing</td><td style="text-align:left;">Seed qua constraint và trigger thật của DB, có test tích hợp</td></tr><tr><td style="text-align:left;">Mobile đang có nhiều thay đổi chưa commit</td><td style="text-align:left;">Chỉ sửa đúng file trong kế hoạch, không dọn thay đổi khác</td></tr></tbody></table>',17)])])}const u=e(i,[["render",o]]);export{m as __pageData,u as default};
